add(법인="Rothera Exchange and Clearing LLC",소재지="미국",시작="2026-01",무엇을="Rothera E&C는 CFTC 인가 선물 거래소(DCM), 청산소(DCO), 스와프 거래장(SEF)이며 예측시장을 포함한 선물과 파생 상품을 냄. Robinhood가 Rothera CEO 선임권과 이사회 과반을 가져 연결 대상으로 봄. Rothera는 자체 경영진과 직원이 운영",값="",단위="",잰것="",기준일="2026-09-30",이유="",틀="밸류체인 > 예측시장 거래소",S="S2RH-S03",문장="On January 20, 2026, Rothera acquired 90% of the issued and outstanding equity of Rothera E&C, a CFTC-licensed DCM, DCO, and SEF. Rothera E&C offers futures and derivative products, including prediction markets.",위치="위험요인 Rothera 항목",검증=P,인가="CFTC DCM, DCO, SEF")
add(법인="Rothera LLC",소재지="미국",시작="2025-11",무엇을="합작 거래소는 MIAXdx를 사서 서비스 시작을 앞당김. 거래소는 Robinhood Derivatives와 다른 선물 중개사(FCM)를 고객으로 받음",값="",단위="",잰것="",기준일="2025-11-25",이유="MIAXdx 인수로 서비스 시작을 앞당김",틀="확장 > 인수 > MIAXdx 이유",S="S2RH-S21",문장="The venture will accelerate delivery of its services by acquiring MIAXdx, a CFTC-licensed Designated Contract Market (DCM), Derivatives Clearing Organization (DCO) and Swap Execution Facility (SEF)",위치="본문 3단락",검증=P)
add(법인="Robinhood Derivatives, LLC; Rothera Exchange and Clearing LLC",소재지="미국",시작="2026-06",무엇을="2026-06-04부터 월드컵과 프로야구 계약 일부를 합작 거래소 Rothera로 보내기 시작. 2026-06-01부터 이벤트 계약 수수료를 계약 가격과 주문 크기에 따라 바꾸는 방식으로 바꾸고 계약당 1센트를 넘지 않게 함(Gold 회원은 최대 50% 낮음). 거래소는 별도 수수료를 받음",값="0.01",단위="USD(계약당 수수료 상한)",잰것="Robinhood 이벤트 계약 수수료 상한",기준일="2026-06-04",이유="",틀="밸류체인 > 예측시장",S="S2RH-S22",문장="On June 1, we introduced a new pricing model where commission fees change based on the price of the contract and the size of the order, with lower fees at the extremes (contracts priced near $0.01 and $0.99) and never exceeding $0.01 per contract. ... Exchanges typically charge an additional fee, which varies by exchange.",위치="본문 2단락, 하단 요금 단락",검증=P)
add(법인="Robinhood Derivatives, LLC",소재지="미국",시작="2026-06",무엇을="이벤트 계약 수수료 공식 = k x 가격 x (1 - 가격) x 계약 수, 센트 단위 올림, 계약당 상한 1센트(예: Gold 5%, 일반 10%). 거래소는 거래소마다 계약당 최대 1센트를 따로 받음. 이벤트 계약은 Robinhood Derivatives가 KalshiEX, ForecastEX, Rothera Exchange and Clearing, Crypto.com Derivatives North America를 통해 냄",값="0.01",단위="USD",잰것="계약당 Robinhood 수수료 상한, 거래소 수수료 상한",기준일="2026-11-17",이유="",틀="밸류체인 > 예측시장",S="S2RH-S23",문장="Commission = (k * p * (1 − p) * c) ... We round up to the nearest $0.01 on all trades with a maximum commission rate of $0.01 per contract. Exchanges typically charge an additional fee, which varies by exchange and can be up to $0.01 per contract.",위치="Fees and commissions",검증=P)
add(법인="Robinhood Markets, Inc.",시작="2026-09",무엇을="2026 Q3 이벤트 계약 매출 1.73억 달러, 거래된 계약 164억 건. 계약 1건당 매출 약 1.05센트(우리 계산). 회사는 이벤트 계약 매출을 중개 수수료와 거래소 몫으로 나누어 밝히지 않음",값="0.0105",단위="USD(계약당, 우리 계산)",잰것="이벤트 계약 매출 ÷ 거래 계약 수",기준일="2026-09-30",이유="",틀="지금 돈 버는 곳 > 예측시장",S="S2RH-S01",문장="event contracts revenue of $173 million, up over 6x ... Event Contracts Traded increased over 7x year-over-year to a record 16.4 billion.",위치="Third Quarter Results, Additional Operating Data",검증=P)
add(법인="Robinhood Markets, Inc.",시작="2026-02",무엇을="Event Contracts Traded 정의: 예측시장 허브에서 사고판 이벤트 계약 수. 계약 하나는 1센트 단위로 1달러까지 거래되고 정산 때 1달러",값="1",단위="USD(정산가)",잰것="",기준일="2025-12-31",이유="",틀="지금 돈 버는 곳 > 예측시장",S="S2RH-S07",문장="We define Event Contracts Traded as the total number of event contracts bought or sold over a specified period of time through our Prediction Markets Hub. Each contract can be traded at $0.01 increments up to $1 and is worth $1 upon settlement.",위치="Key Performance Metrics",검증=P)
add(법인="Bitstamp Ltd.",소재지="룩셈부르크 등",시작="2024-06",무엇을="Bitstamp(2011 설립, 룩셈부르크, 영국, 슬로베니아, 싱가포르, 미국 사무소)는 50개 넘는 인가와 등록을 가짐. 인수로 Robinhood의 첫 기관 사업이 생김(호가창, API, 화이트라벨 Bitstamp-as-a-service, 기관 대출, 스테이킹). 현물 거래소 85종 넘는 자산. 대가 약 2억 달러 현금 예상, 2025-06-02 완료",값="50; 85; 200",단위="개; 종; 백만 USD",잰것="인가와 등록 수; 거래 자산 수; 예상 대가",기준일="2024-06-06",이유="해외 확장을 크게 앞당기고 첫 기관 사업을 들임",틀="확장 > 인수 > Bitstamp",S="S2RH-S14",문장="Acquiring a global exchange will significantly accelerate Robinhood Crypto's expansion worldwide. Bitstamp holds over 50 active licenses and registrations globally and will bring in customers across the EU, UK, US and Asia to Robinhood. This acquisition will introduce Robinhood's first institutional business.",위치="본문 2~3단락",검증=P)
add(법인="Robinhood Markets, Inc.",시작="2025-06",무엇을="가상자산 사업은 외부 은행, 유동성 공급자, 가상자산 거래소에 크게 기대며, 예외는 2025-06 인수한 Bitstamp가 운영하는 거래소라고 공시. 즉 Bitstamp 전에는 자기 가상자산 거래소가 없었음",값="",단위="",잰것="",기준일="2026-09-30",이유="",틀="확장 > 인수 > Bitstamp 그 전",S="S2RH-S03",문장="We rely heavily on third-party banks, Liquidity Providers, and cryptocurrency exchanges in connection with our provision of cryptocurrency products and services to our customers, with the exception of a cryptocurrency exchange operated by Bitstamp and acquired by Robinhood in June 2025.",위치="위험요인 가상자산 항목",검증=P)
add(법인="Bitstamp 법인들",시작="2025-06",무엇을="Bitstamp 인수로 미국 일부와 해외 기관 고객에게 대출, 거래소 안 대출, 거래소 밖 결제, 거래 후 결제, 무기한선물 거래소 같은 가상자산 상품을 팔게 됨",값="",단위="",잰것="",기준일="2026-09-30",이유="",틀="확장 > 인수 > Bitstamp 그 뒤",S="S2RH-S03",문장="As a result of our acquisition of Bitstamp, we now provide additional cryptocurrency products and services to institutional customers both in parts of the U.S. and internationally, including products and services such as retail lending, on-exchange lending, off-exchange settlement, post-trade settlement, and perpetual futures exchange.",위치="위험요인 신용 위험 항목",검증=P)
add(법인="TradePMR",소재지="미국 플로리다 게인즈빌",시작="2024-11",무엇을="TradePMR은 독립 투자자문사(RIA)용 계좌 보관과 포트폴리오 관리 플랫폼(Fusion). 자문사 약 350곳, 관리 자산 400억 달러 넘음. FINRA 회원 증권사이자 보관 회사. 체결, 청산, 대출은 Wells Fargo Clearing Services가 맡음. 대가 약 3억 달러(현금과 주식 섞음) 예상, 2025-02-26 완료. 발표 당시 Robinhood 펀디드 계좌 2,400만 개 중 약 75%가 밀레니얼과 Z세대",값="350; 40; 300; 75",단위="곳; 십억 USD; 백만 USD; %",잰것="자문사 수; 관리 자산; 예상 대가; 젊은 세대 비중",기준일="2024-11-19",이유="자문 기능을 앞당기고 자문사와 Robinhood 고객을 잇는 소개 프로그램을 만들려고",틀="확장 > 인수 > TradePMR",S="S2RH-S15",문장="TradePMR has a long-standing partnership with Wells Fargo Clearing Services, LLC, a subsidiary of Wells Fargo & Company, which provides clearing, execution, and lending services to TradePMR ... Final deal consideration is expected to be approximately $300 million, subject to customary purchase price adjustments, consisting of a mix of cash and stock.",위치="본문 Continuity 단락, 대가 단락",검증=P)
add(법인="WonderFi Technologies Inc.",소재지="캐나다",시작="2025-05",무엇을="WonderFi는 캐나다에서 가장 오래 운영된 규제 가상자산 플랫폼 두 곳(Bitbuy, Coinsquare)을 운영, 보관 자산 21억 캐나다달러 넘음. 주당 0.36캐나다달러 전액 현금, 지분가치 약 2.5억 캐나다달러, 보유 현금으로 지급",값="2.1; 250",단위="십억 CAD; 백만 CAD",잰것="보관 자산; 인수 지분가치",기준일="2025-05-13",이유="캐나다는 빠르게 크는 가상자산 시장",틀="확장 > 인수 > WonderFi",S="S2RH-S16",문장="WonderFi operates two of Canada's longest-standing regulated crypto platforms, with more than C$2.1 billion in assets under custody. ... The all-cash purchase price represents a total equity value of approximately C$250 million on a fully diluted, in-the-money basis",위치="본문 1단락, 대가 단락",검증=P)
add(법인="WonderFi Technologies Inc.",소재지="캐나다",시작="2026-06",무엇을="2026-06-01 WonderFi 인수 완료로 캐나다 진출. WonderFi에서 돈이 들어 있는 고객 약 30만 명이 더해져 해외 펀디드 고객 100만 명 넘음. Bitbuy와 Coinsquare는 Robinhood 브랜드로 들어오고, 캐나다 고객을 Robinhood 앱으로 초대해 캐나다달러 거래 1회 0.5% 고정 수수료. WonderFi의 기관 관계도 이어 감",값="300000; 1000000; 0.5",단위="명; 명; %",잰것="WonderFi 펀디드 고객; 해외 펀디드 고객; 캐나다달러 거래 수수료",기준일="2026-06-01",이유="캐나다에서 신뢰받는 가상자산 상품을 내려고",틀="확장 > 인수 > WonderFi 그 뒤",S="S2RH-S17",문장="Robinhood now has more than 1 million international funded customers, including approximately 300,000 funded customers from WonderFi.",위치="본문 4단락",검증=P)
add(법인="WonderFi Technologies Inc.",소재지="캐나다",시작="2025-03",무엇을="WonderFi 2024년 매출과 이자수입 6,210만 캐나다달러(1년 전보다 108% 증가), 가상자산 거래대금 35.7억 캐나다달러, 2024 말 보관 자산 21억 캐나다달러",값="62.1; 3.57; 2.1",단위="백만 CAD; 십억 CAD; 십억 CAD",잰것="2024 매출과 이자수입; 거래대금; 보관 자산",기준일="2024-12-31",이유="",틀="확장 > 인수 > WonderFi 규모",S="S2RH-S18",문장="Bitbuy, Coinsquare, and SmartPay generated combined revenue and interest income of $62.1 million in 2024, representing a 108% increase compared with Fiscal Year 2023.",위치="Financial Highlights",검증=P)
add(법인="Coinsquare Capital Markets Ltd.",소재지="캐나다",시작="2026-05",무엇을="WonderFi 자회사 CCML이 캐나다 투자산업 자율규제기구(CIRO)로부터 Robinhood 인수에 대한 승인을 2026-05-20 받음. 주주 승인은 2025-07-17, 법원 최종 명령 2025-07-21. 이 승인 뒤 추가 규제 승인 불필요",값="",단위="",잰것="",기준일="2026-05-20",이유="",틀="확장 > 인수 > WonderFi 걸린 시간",S="S2RH-S19",문장="Coinsquare Capital Markets Ltd. (\"CCML\"), WonderFi's wholly-owned subsidiary, received regulatory approval from the Canadian Investment Regulatory Organization (\"CIRO\") for Robinhood Markets, Inc.'s ... previously announced acquisition of WonderFi ... The CIRO Approval was received on May 20, 2026.",위치="본문 1단락",검증=P,인가="CIRO 회원 투자딜러")
add(법인="Coinsquare Capital Markets Ltd.",소재지="캐나다",시작="2024-10",무엇을="온타리오 증권위원회(OSC) 등록 가상자산 거래 플랫폼 목록(13곳)에 Coinsquare Capital Markets Ltd.(Bitbuy 이름으로도 영업)가 투자딜러(Investment Dealer) 등록으로 올라 있음. 같은 목록에서 Coinbase Canada, Kraken(Payward Canada), Crypto.com은 제한딜러(Restricted Dealer). Bitbuy Technologies의 옛 제한딜러 등록은 Coinsquare가 사업을 인수해 만료",값="13",단위="곳",잰것="OSC 등록 가상자산 거래 플랫폼 수",기준일="2026-11-15",이유="",틀="확장 > 인수 > WonderFi 인가",S="S2RH-S20",문장="Coinsquare Capital Markets Ltd., also carrying on business as Bitbuy | Investment Dealer (Dealer) | Amended Decision (October 9, 2026) Decision (October 11, 2024)",위치="Registered crypto asset trading platforms 표",검증=P,인가="캐나다 투자딜러(CIRO)")
add(법인="Robinhood Markets, Inc.",시작="",무엇을="Cash Sweep 정의: 참여 고객의 투자하지 않은 증권 계좌와 은행 계좌 현금을 제휴 은행 예금으로 자동으로 옮긴 잔액(재무상태표 밖). Robinhood는 은행이 주는 금리와 고객에게 주는 금리의 차이를 순이자로 얻음. TradePMR 자문사 고객 잔액 포함",값="",단위="",잰것="",기준일="2026-09-30",이유="",틀="지금 돈 버는 곳 > 순이자",S="S2RH-S03",문장="Robinhood earns a net interest spread on Cash Sweep balances based on the interest rate offered by the banks less the interest rate given to users as stated in our program terms. This includes balances from customers of RIAs using TradePMR's platform.",위치="용어 정의 표 Cash Sweep",검증=P)
